public EnterpriseStockReport(final org.cocome.tradingsystem.inventory.application.reporting.ReportingIf rep, final javax.swing.JFrame frame) {
    super(new java.awt.BorderLayout());
    javax.swing.JPanel pan = new javax.swing.JPanel(new java.awt.BorderLayout());
    pan.add(new javax.swing.JLabel("Enter enterprise id and press 'Create Report'"), java.awt.BorderLayout.NORTH);
    final javax.swing.JTextField field = new javax.swing.JTextField();
    pan.add(field, java.awt.BorderLayout.SOUTH);
    this.add(pan, java.awt.BorderLayout.NORTH);
    final javax.swing.JButton button = new javax.swing.JButton("Create Report");
    this.add(button, java.awt.BorderLayout.SOUTH);
    final javax.swing.JTextPane textpane = new javax.swing.JTextPane();
    textpane.setEditorKit(new javax.swing.text.html.HTMLEditorKit());
    javax.swing.JScrollPane scrollPane = new javax.swing.JScrollPane(textpane);
    this.add(scrollPane, java.awt.BorderLayout.CENTER);
    button.addActionListener(new java.awt.event.ActionListener() {
        1() {
            super();
        }

        public void actionPerformed(java.awt.event.ActionEvent arg0) {
            if (arg0.getSource() == button) {
                java.lang.String btext = field.getText();
                long epId;
                try {
                    epId = java.lang.Long.parseLong(btext);
                } catch (java.lang.NumberFormatException e) {
                    field.setText("");
                    // TODO: Pop- up error dialog
                    e.printStackTrace();
                    return;
                }
                org.cocome.tradingsystem.inventory.application.reporting.EnterpriseTO ep = new org.cocome.tradingsystem.inventory.application.reporting.EnterpriseTO();
                ep.setId(epId);
                org.cocome.tradingsystem.inventory.application.reporting.ReportTO report;
                try {
                    report = rep.getStockReport(ep);
                } catch (java.rmi.RemoteException e) {
                    // TODO Auto-generated catch block
                    e.printStackTrace();
                    return;
                }
                textpane.setText(report.getReportText());
                field.setText("");
            }
        }
    });
}

