public void onEvent(org.cocome.tradingsystem.cashdeskline.events.PaymentModeEvent paymentModeEvent) {
    this.log.info("Application: PaymentModeEvent received");
    if (this.currState.equals(org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.SALE_FINISHED) || this.currState.equals(org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.PAYING_BY_CREDITCARD)) {
        org.cocome.tradingsystem.cashdeskline.datatypes.PaymentMode mode = paymentModeEvent.getMode();
        if (mode.equals(org.cocome.tradingsystem.cashdeskline.datatypes.PaymentMode.CASH)) {
            this.currState = org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.PAYING_BY_CASH;
        }
        if (mode.equals(org.cocome.tradingsystem.cashdeskline.datatypes.PaymentMode.CREDITCARD) && (!this.expressModeEnabled)) {
            this.currState = org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.PAYING_BY_CREDITCARD;
        }
    }
}

