private static void registerAtMessageQueue(java.lang.String topicName, final org.cocome.tradingsystem.inventory.application.store.CashDeskConnectorIf store) throws javax.jms.JMSException, javax.naming.NamingException {
    javax.naming.Context jndiContext = new javax.naming.InitialContext();
    // get TopicConnectionFactory
    javax.jms.TopicConnectionFactory channelConnectionFactory = ((javax.jms.TopicConnectionFactory) (jndiContext.lookup(org.cocome.tradingsystem.inventory.application.ApplicationFactory.CHANNEL_CONNECTION_FACTORY)));
    // createTopicConnection
    javax.jms.TopicConnection topicConnection = channelConnectionFactory.createTopicConnection();
    // createTopicSession
    javax.jms.TopicSession topicSession = topicConnection.createTopicSession(false, Session.AUTO_ACKNOWLEDGE);
    // getTopic
    javax.jms.Topic storeTopic = ((javax.jms.Topic) (jndiContext.lookup(topicName)));
    javax.jms.TopicSubscriber externalSubscriber = topicSession.createSubscriber(storeTopic);
    externalSubscriber.setMessageListener(new javax.jms.MessageListener() {
        public void onMessage(javax.jms.Message message) {
            if (message instanceof javax.jms.ObjectMessage) {
                javax.jms.ObjectMessage objMessage = ((javax.jms.ObjectMessage) (message));
                try {
                    java.io.Serializable eventObject = objMessage.getObject();
                    // A AccountSaleEvent has been received
                    if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.AccountSaleEvent) {
                        org.cocome.tradingsystem.cashdeskline.events.AccountSaleEvent accountSaleEvent = ((org.cocome.tradingsystem.cashdeskline.events.AccountSaleEvent) (eventObject));
                        org.cocome.tradingsystem.inventory.application.ApplicationFactory.log.info("AccountSaleEvent received");
                        try {
                            store.bookSale(accountSaleEvent.getSale());
                        } catch (java.rmi.RemoteException e) {
                            // never happens, called locally
                        }
                    }
                } catch (javax.jms.JMSException e) {
                    e.printStackTrace();
                }
            }
        }
    });
    topicConnection.start();
}

