public org.cocome.tradingsystem.inventory.application.store.ProductWithStockItemTO getProductWithStockItem(long productBarCode) throws org.cocome.tradingsystem.inventory.application.store.NoSuchProductException {
    org.cocome.tradingsystem.inventory.application.store.ProductWithStockItemTO result = null;
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        org.cocome.tradingsystem.inventory.data.store.StockItem stockitem = this.storequery.queryStockItem(this.storeid, productBarCode, pctx);
        if (stockitem == null) {
            tx.commit();
            throw new org.cocome.tradingsystem.inventory.application.store.NoSuchProductException("There exists no product with barcode " + productBarCode);
        }
        result = org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillProductWithStockItemTO(stockitem);
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
    return result;
}

