public void onMessage(javax.jms.Message message) {
    if (message instanceof javax.jms.ObjectMessage) {
        javax.jms.ObjectMessage objMessage = ((javax.jms.ObjectMessage) (message));
        try {
            java.io.Serializable eventObject = objMessage.getObject();
            // A ExpressModeEnabledEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent expressModeEnabledEvent = ((org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent) (eventObject));
                this.onEvent(expressModeEnabledEvent);
            }
            // A ExpressModeDisabledEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent expressModeDisabledEvent = ((org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent) (eventObject));
                this.onEvent(expressModeDisabledEvent);
            }
        } catch (javax.jms.JMSException e) {
            e.printStackTrace();
        }
    }
}

public void onEvent(org.cocome.tradingsystem.cashdeskline.events.ProductBarcodeScannedEvent productBarcodeScannedEvent) {
    this.log.info(("Application: ProductBarcodeScannedEvent(" + productBarcodeScannedEvent.getScannedBarcode()) + ") received");
    if (this.currState.equals(org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.SALE_STARTED)) {
        // stop scanning if more than 8 products in express mode
        if (this.expressModeEnabled && (this.products.size() == 8)) {
            return;
        }
        org.cocome.tradingsystem.inventory.application.store.ProductWithStockItemTO product = null;
        try {
            try {
                product = this.inventory.getProductWithStockItem(productBarcodeScannedEvent.getScannedBarcode());
            } catch (org.cocome.tradingsystem.inventory.application.store.NoSuchProductException e) {
                this.log.error(e.getMessage());
                this.appPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.ProductBarcodeNotValidEvent(productBarcodeScannedEvent.getScannedBarcode())));
                this.topicSession.commit();
                return;
            }
            java.lang.String productname = product.getName();
            double price = product.getStockItemTO().getSalesPrice();
            // calculate running total
            this.runningtotal += price;
            // round
            this.runningtotal = java.lang.Math.rint(100 * this.runningtotal) / 100;
            // send event to GUI
            this.appPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.RunningTotalChangedEvent(productname, price, this.runningtotal)));
            this.topicSession.commit();
            // if crash here, abort anyway
            this.products.add(product);
        } catch (java.rmi.RemoteException e) {
            e.printStackTrace();
            try {
                this.topicSession.rollback();
            } catch (javax.jms.JMSException e1) {
                e1.printStackTrace();
            }
        } catch (javax.jms.JMSException e) {
            e.printStackTrace();
            try {
                this.topicSession.rollback();
            } catch (javax.jms.JMSException e1) {
                e1.printStackTrace();
            }
        }
    } else {
        try {
            this.topicSession.commit();
        } catch (javax.jms.JMSException e) {
            e.printStackTrace();
        }
    }
}

