public void onEvent(org.cocome.tradingsystem.cashdeskline.events.CashAmountEnteredEvent cashAmountEnteredEvent) {
    this.log.info("CashAmountEnteredEvent received");
    if (this.state.equals(org.cocome.tradingsystem.cashdeskline.cashdesk.printercontroller.impl.PrinterStates.SALE_FINISHED)) {
        switch (cashAmountEnteredEvent.getKeyStroke()) {
            case ONE :
                this.printercontroller.append("1");
                break;
            case TWO :
                this.printercontroller.append("2");
                break;
            case THREE :
                this.printercontroller.append("3");
                break;
            case FOUR :
                this.printercontroller.append("4");
