public void onEvent(org.cocome.tradingsystem.cashdeskline.events.CashAmountEnteredEvent cashAmountEnteredEvent) {
    this.log.info("Application: CashAmountEnteredEvent received");
    if (this.currState.equals(org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.PAYING_BY_CASH)) {
        switch (cashAmountEnteredEvent.getKeyStroke()) {
            case ONE :
                this.total = this.total.append("1");
                break;
            case TWO :
                this.total = this.total.append("2");
                break;
            case THREE :
                this.total = this.total.append("3");
                break;
            case FOUR :
                this.total = this.total.append("4");
                break;
            case FIVE :
                this.total = this.total.append("5");
                break;
            case SIX :
                this.total = this.total.append("6");
                break;
            case SEVEN :
                this.total = this.total.append("7");
                break;
            case EIGHT :
                this.total = this.total.append("8");
                break;
            case NINE :
                this.total = this.total.append("9");
                break;
            case ZERO :
                this.total = this.total.append("0");
                break;
            case COMMA :
                this.total = this.total.append(".");
                break;
            case ENTER :
                try {
                    double amount = java.lang.Double.parseDouble(this.total.toString());
                    double changeamount = amount - this.runningtotal;
                    // round
                    changeamount = java.lang.Math.rint(100 * changeamount) / 100;
                    this.appPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.ChangeAmountCalculatedEvent(changeamount)));
                    this.topicSession.commit();
                    this.currState = org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.PAID;
                    return;
                } catch (java.lang.NumberFormatException e) {
                    // TODO: Handle properly
                    this.log.error(e.toString());
                } catch (javax.jms.JMSException e) {
                    this.log.error(e.toString());
                    e.printStackTrace();
                }
                break;
        }
    }
}

