public org.cocome.tradingsystem.inventory.application.store.ProductWithStockItemTO changePrice(org.cocome.tradingsystem.inventory.application.store.StockItemTO stockItemTO) {
    org.cocome.tradingsystem.inventory.application.store.ProductWithStockItemTO result = new org.cocome.tradingsystem.inventory.application.store.ProductWithStockItemTO();
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        org.cocome.tradingsystem.inventory.data.store.StockItem si = this.storequery.queryStockItemById(stockItemTO.getId(), pctx);
        si.setSalesPrice(stockItemTO.getSalesPrice());
        result = org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillProductWithStockItemTO(si);
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
