/* (non-Javadoc)
@see org.cocome.tradingsystem.inventory.application.productdispatcher.ProductDispatcherIf#isProductAvailableAtOtherStores(org.cocome.tradingsystem.inventory.application.reporting.StoreTO, org.cocome.tradingsystem.inventory.application.store.ProductTO[])
 */
public org.cocome.tradingsystem.inventory.application.store.ProductAmountTO[] orderProductsAvailableAtOtherStores(org.cocome.tradingsystem.inventory.application.reporting.EnterpriseTO enterpriseTO, org.cocome.tradingsystem.inventory.application.reporting.StoreTO callingStore, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> productAmounts) {
    this.pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.application.store.ProductAmountTO[] result = null;
    org.cocome.tradingsystem.inventory.data.enterprise.TradingEnterprise enterprise = this.enterpriseQuery.queryEnterpriseById(enterpriseTO.getId(), this.pctx);
    java.util.Collection<org.cocome.tradingsystem.inventory.data.store.Store> stores = enterprise.getStores();
    // distributed action:
    this.letAllStoresFlushDatabase(this.pctx, stores);
    // solve the optimization problem using ampl/cplex:
    long[] productIds = this.getProductIds(productAmounts);
    org.cocome.tradingsystem.inventory.application.productdispatcher.OptimisationSolverIf solver = new org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter(this.pctx);
    java.util.Hashtable<org.cocome.tradingsystem.inventory.application.reporting.StoreTO, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>> storeProductAmounts = solver.solveOptimization(productAmounts, this.getOfferedStockItemsPerStore(stores, productIds), this.getStoreDistances(stores, callingStore));
    // distributed action:
    this.markProductsUnavailableInStock(storeProductAmounts, callingStore);
    result = this.sumUpIncomingProducts(storeProductAmounts);
    return result;
}

