                org.cocome.tradingsystem.cashdeskline.events.ChangeAmountCalculatedEvent changeAmountCalculatedEvent = ((org.cocome.tradingsystem.cashdeskline.events.ChangeAmountCalculatedEvent) (eventObject));
                this.onEvent(changeAmountCalculatedEvent);
            }
            // A SaleStartedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.SaleStartedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.SaleStartedEvent saleStartedEvent = ((org.cocome.tradingsystem.cashdeskline.events.SaleStartedEvent) (eventObject));
                this.onEvent(saleStartedEvent);
