            // A SaleSuccessEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.SaleSuccessEvent) {
                org.cocome.tradingsystem.cashdeskline.events.SaleSuccessEvent saleSuccessEvent = ((org.cocome.tradingsystem.cashdeskline.events.SaleSuccessEvent) (eventObject));
                this.onEvent(saleSuccessEvent);
