private java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> calculateProductAmounts(java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem> lowRunningStockItems) {
    java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> productAmounts = new java.util.ArrayList<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>();
    java.util.Iterator<org.cocome.tradingsystem.inventory.data.store.StockItem> stockItemsIterator = lowRunningStockItems.iterator();
    while (stockItemsIterator.hasNext()) {
        org.cocome.tradingsystem.inventory.data.store.StockItem currentStockItem = stockItemsIterator.next();
        // do not exeed stock limits:
        long orderAmount = currentStockItem.getMinStock();
        if ((2 * currentStockItem.getMinStock()) >= currentStockItem.getMaxStock()) {
            orderAmount = currentStockItem.getMaxStock() - currentStockItem.getMinStock();
        }
        org.cocome.tradingsystem.inventory.application.store.ProductAmountTO pa = new org.cocome.tradingsystem.inventory.application.store.ProductAmountTO();
        pa.setProduct(org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillProductTO(currentStockItem.getProduct()));
        pa.setAmount(orderAmount);
        productAmounts.add(pa);
    } 
    return productAmounts;
}

