        tx.beginTransaction();
        java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem> stockitems = this.storequery.queryLowStockItems(this.storeid, pctx);
        for (org.cocome.tradingsystem.inventory.data.store.StockItem s : stockitems) {
