public void onMessage(javax.jms.Message message) {
    if (message instanceof javax.jms.ObjectMessage) {
        javax.jms.ObjectMessage objMessage = ((javax.jms.ObjectMessage) (message));
        try {
            java.io.Serializable eventObject = objMessage.getObject();
            // A SaleStartedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.SaleStartedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.SaleStartedEvent saleStartedEvent = ((org.cocome.tradingsystem.cashdeskline.events.SaleStartedEvent) (eventObject));
                this.onEvent(saleStartedEvent);
            }
            // A ProductBarcodeScannedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ProductBarcodeScannedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ProductBarcodeScannedEvent barcodeEvent = ((org.cocome.tradingsystem.cashdeskline.events.ProductBarcodeScannedEvent) (eventObject));
                this.onEvent(barcodeEvent);
            }
            // A SaleFinishedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.SaleFinishedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.SaleFinishedEvent saleFinishedEvent = ((org.cocome.tradingsystem.cashdeskline.events.SaleFinishedEvent) (eventObject));
                this.onEvent(saleFinishedEvent);
            }
            // A CashAmountEnteredEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.CashAmountEnteredEvent) {
                org.cocome.tradingsystem.cashdeskline.events.CashAmountEnteredEvent cashAmountEnteredEvent = ((org.cocome.tradingsystem.cashdeskline.events.CashAmountEnteredEvent) (eventObject));
                this.onEvent(cashAmountEnteredEvent);
            }
            // A CashBoxClosedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.CashBoxClosedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.CashBoxClosedEvent cashBoxClosedEvent = ((org.cocome.tradingsystem.cashdeskline.events.CashBoxClosedEvent) (eventObject));
                this.onEvent(cashBoxClosedEvent);
            }
            // A CreditCardScannedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.CreditCardScannedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.CreditCardScannedEvent creditCardScannedEvent = ((org.cocome.tradingsystem.cashdeskline.events.CreditCardScannedEvent) (eventObject));
                this.onEvent(creditCardScannedEvent);
            }
            // A PINEnteredEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.PINEnteredEvent) {
                org.cocome.tradingsystem.cashdeskline.events.PINEnteredEvent pinEnteredEvent = ((org.cocome.tradingsystem.cashdeskline.events.PINEnteredEvent) (eventObject));
                this.onEvent(pinEnteredEvent);
            }
            // A ExpressModeEnabledEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent expressModeEnabledEvent = ((org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent) (eventObject));
                this.onEvent(expressModeEnabledEvent);
            }
            // A ExpressModeDisabledEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent expressModeDisabledEvent = ((org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent) (eventObject));
                this.onEvent(expressModeDisabledEvent);
            }
            // A PaymentModeEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.PaymentModeEvent) {
                org.cocome.tradingsystem.cashdeskline.events.PaymentModeEvent paymentModeEvent = ((org.cocome.tradingsystem.cashdeskline.events.PaymentModeEvent) (eventObject));
                this.onEvent(paymentModeEvent);
            }
        } catch (javax.jms.JMSException e) {
            e.printStackTrace();
        }
    }
}

protected ScannerControllerEventHandlerImpl(java.lang.String eventchannel) {
    super();
    try {
        this.topicName = eventchannel;
        this.jndiContext = new javax.naming.InitialContext();
        // get TopicConnectionFactory
        this.channelConnectionFactory = ((javax.jms.TopicConnectionFactory) (this.jndiContext.lookup(this.CHANNEL_CONNECTION_FACTORY)));
        // createTopicConnection
        this.topicConnection = this.channelConnectionFactory.createTopicConnection();
        // createTopicSession
        this.topicSession = this.topicConnection.createTopicSession(false, Session.AUTO_ACKNOWLEDGE);
        // getTopic
        this.cashDeskTopic = ((javax.jms.Topic) (this.jndiContext.lookup(this.topicName)));
        this.barcodePublisher = this.topicSession.createPublisher(this.cashDeskTopic);
    } catch (javax.naming.NamingException e) {
        e.printStackTrace();
    } catch (javax.jms.JMSException e) {
        e.printStackTrace();
    }
}

