/* Checks the condition for UC 2:ManageExpressCheckout:
50% of all sales during the last 60 minutes meet the requirements of an express checkout.
That is: up to 8 products per sale and customer pays cash.
 */
private boolean isExpressModeNeeded() {
    java.util.Date now = new java.util.Date();
    int meetscondition = 0;
    int total = 0;
    // clean list of old (non-relevant) entries
    for (java.util.Iterator<org.cocome.tradingsystem.cashdeskline.coordinator.impl.Sale> i = this.sales.iterator(); i.hasNext();) {
        org.cocome.tradingsystem.cashdeskline.coordinator.impl.Sale s = i.next();
        if ((s.getTimeofSale().getTime() + 3600000) < now.getTime()) {
            i.remove();
        } else {
            if (s.getPaymentmode().equals(org.cocome.tradingsystem.cashdeskline.datatypes.PaymentMode.CASH) && (s.getNumberofItems() <= 8)) {
                meetscondition++;
            }
            total++;
        }
    }
    if ((((double) (meetscondition)) / ((double) (total))) > 0.5) {
        return true;
    }
    return false;
}

public void rollInReceivedOrder(org.cocome.tradingsystem.inventory.application.store.ComplexOrderTO complexOrderTO) {
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        org.cocome.tradingsystem.inventory.data.store.ProductOrder po = this.storequery.queryOrderById(complexOrderTO.getId(), pctx);
        if (po == null) {
            // TODO: throw exception
            throw new java.lang.NullPointerException();
        }
        if (po.getDeliveryDate() != null) {
            java.lang.System.out.println("already rolled in");
            // Already delivered
            // TODO: throw exception
            return;
        }
        if (po.getStore().getId() != this.storeid) {
            java.lang.System.out.println("Cannot be executed by this store");
            // Cannot be executed by this store
            // TODO: throw exception
            return;
        }
        // set DeliveryDate to NOW
        po.setDeliveryDate(new java.util.Date());
        for (org.cocome.tradingsystem.inventory.data.store.OrderEntry oe : po.getOrderEntries()) {
            org.cocome.tradingsystem.inventory.data.store.StockItem si = this.storequery.queryStockItem(this.storeid, oe.getProduct().getBarcode(), pctx);
            si.setAmount(si.getAmount() + oe.getAmount());
        }
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
}

