public void onEvent(org.cocome.tradingsystem.cashdeskline.events.SaleRegisteredEvent saleRegisteredEvent) {
    this.log.info("SaleRegisteredEvent received");
    this.updateStatistics(saleRegisteredEvent.getNumberOfItems(), saleRegisteredEvent.getPaymentMode());
    if (this.isExpressModeNeeded()) {
        this.log.info("ExpressMode activated");
        try {
            this.coordinatorPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent(saleRegisteredEvent.getCashdesk())));
        } catch (javax.jms.JMSException e) {
            this.log.warn(e.getMessage());
            e.printStackTrace();
        }
    } else {
        // The disabling of the ExpressMode is done manually by the cashier
        // at the CashDeskGUI
    }
}

