public org.cocome.tradingsystem.inventory.application.reporting.ReportTO getStockReport(org.cocome.tradingsystem.inventory.application.reporting.EnterpriseTO enterpriseTO) {
    org.cocome.tradingsystem.inventory.application.reporting.ReportTO result = new org.cocome.tradingsystem.inventory.application.reporting.ReportTO();
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    java.lang.StringBuilder reportText = new java.lang.StringBuilder("");
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        org.cocome.tradingsystem.inventory.data.enterprise.TradingEnterprise enterprise = this.enterprisequery.queryEnterpriseById(enterpriseTO.getId(), pctx);
        reportText.append("<html><body>");
        reportText.append(("Stock report for enterprise " + enterprise.getName()) + " <br/>");
        for (org.cocome.tradingsystem.inventory.data.store.Store store : enterprise.getStores()) {
            org.cocome.tradingsystem.inventory.application.reporting.StoreTO storeTO = new org.cocome.tradingsystem.inventory.application.reporting.StoreTO();
            storeTO.setId(store.getId());
            this.append(reportText, storeTO, pctx);
        }
        reportText.append("</body></html>");
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
    result.setReportText(reportText.toString());
    return result;
}

