private void checkForLowRunningGoods() {
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem> lowRunningStockItems = this.storequery.queryLowStockItems(this.storeid, pctx);
    java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> productAmounts = this.calculateProductAmounts(lowRunningStockItems);
    org.cocome.tradingsystem.inventory.data.store.Store thisStore = this.storequery.queryStoreById(this.storeid, pctx);
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    org.cocome.tradingsystem.inventory.application.store.ProductAmountTO[] incomingProductAmounts;
    try {
        // TODO: should be a remote call:
        incomingProductAmounts = org.cocome.tradingsystem.inventory.application.ApplicationFactory.getProductDispatcherInstance().orderProductsAvailableAtOtherStores(org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillEnterpriseTO(thisStore.getEnterprise()), org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillStoreTO(thisStore), productAmounts);
        if (incomingProductAmounts != null) {
            tx = pctx.getTransactionContext();
            tx.beginTransaction();
            for (org.cocome.tradingsystem.inventory.application.store.ProductAmountTO p : incomingProductAmounts) {
                org.cocome.tradingsystem.inventory.data.store.StockItem s = this.storequery.queryStockItem(this.storeid, p.getProduct().getBarcode(), pctx);
                // increase incoming amount by required amount:
                s.setIncomingAmount(s.getIncomingAmount() + p.getAmount());
                java.lang.System.out.println("KK: " + p.getProduct().getId());
            }
            tx.commit();
        } else {
            java.lang.String msg = "incomingProductAmounts not initialized / set";
            java.lang.System.err.println(msg);
        }
    } catch (java.rmi.RemoteException e) {
        e.printStackTrace();
        throw new java.lang.RuntimeException("Error on connecting to the enterprise server. " + "Cannot finish UC 8.", e);
        // TODO: error handling
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
}

