public java.util.List<org.cocome.tradingsystem.inventory.application.store.ComplexOrderTO> orderProducts(org.cocome.tradingsystem.inventory.application.store.ComplexOrderTO complexOrder) {
    java.util.List<org.cocome.tradingsystem.inventory.application.store.ComplexOrderTO> result = new java.util.ArrayList<org.cocome.tradingsystem.inventory.application.store.ComplexOrderTO>();
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        java.util.List<org.cocome.tradingsystem.inventory.data.store.ProductOrder> orders = new java.util.ArrayList<org.cocome.tradingsystem.inventory.data.store.ProductOrder>();
        java.util.HashMap<java.lang.Long, java.util.List<org.cocome.tradingsystem.inventory.data.store.OrderEntry>> ordersuppl = new java.util.HashMap<java.lang.Long, java.util.List<org.cocome.tradingsystem.inventory.data.store.OrderEntry>>();
        for (org.cocome.tradingsystem.inventory.application.store.ComplexOrderEntryTO coeto : complexOrder.getOrderEntryTO()) {
            org.cocome.tradingsystem.inventory.data.enterprise.Product p = this.storequery.queryProductById(coeto.getProductTO().getId(), pctx);
            java.lang.System.out.println("Product found");
            org.cocome.tradingsystem.inventory.data.store.OrderEntry oe = new org.cocome.tradingsystem.inventory.data.store.OrderEntry();
            oe.setProduct(p);
            oe.setAmount(coeto.getAmount());
            pctx.makePersistent(oe);
            long supplierid = p.getSupplier().getId();
            if (!ordersuppl.containsKey(new java.lang.Long(supplierid))) {
                ordersuppl.put(new java.lang.Long(supplierid), new java.util.ArrayList<org.cocome.tradingsystem.inventory.data.store.OrderEntry>());
            }
            ordersuppl.get(new java.lang.Long(supplierid)).add(oe);
        }
        java.lang.System.out.println(ordersuppl);
        for (java.util.List<org.cocome.tradingsystem.inventory.data.store.OrderEntry> loe : ordersuppl.values()) {
            org.cocome.tradingsystem.inventory.data.store.ProductOrder po = new org.cocome.tradingsystem.inventory.data.store.ProductOrder();
            pctx.makePersistent(po);
            po.setOrderEntries(loe);
            po.setStore(this.storequery.queryStoreById(this.storeid, pctx));
            // set OrderingDate to NOW
            po.setOrderingDate(new java.util.Date());
            orders.add(po);
        }
        for (org.cocome.tradingsystem.inventory.data.store.ProductOrder po : orders) {
            result.add(org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillComplexOrderTO(po));
        }
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
    return result;
}

