private static void appendOfferingStoresProductsAmountsMatrix(java.util.Hashtable<org.cocome.tradingsystem.inventory.data.store.Store, java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem>> storeStockItems, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> requiredProductAmounts, java.lang.StringBuffer output) {
    org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.appendMatrixHeader(output, requiredProductAmounts);
    boolean first = true;
    java.util.Enumeration<org.cocome.tradingsystem.inventory.data.store.Store> offeringStores = storeStockItems.keys();
    org.cocome.tradingsystem.inventory.data.store.Store currentOfferingStore;
    java.util.Iterator<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> requiredProductsIterator;
    while (offeringStores.hasMoreElements()) {
        // for each offering store
        if (!first) {
            output.append("\n");
        }
        first = false;
        currentOfferingStore = offeringStores.nextElement();
        java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem> offeredStockItems = storeStockItems.get(currentOfferingStore);
        requiredProductsIterator = requiredProductAmounts.iterator();
        // content rows "StoreId AmountForProductA AmountForProductB ..
        output.append(("\"Store" + currentOfferingStore.getId()) + "\" ");
        while (requiredProductsIterator.hasNext()) {
            org.cocome.tradingsystem.inventory.application.store.ProductAmountTO currentRequiredProduct = requiredProductsIterator.next();
            org.cocome.tradingsystem.inventory.data.store.StockItem stockItem = org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.searchForProductOffered(offeredStockItems, currentRequiredProduct);
            if (stockItem != null) {
                // offered by currentOfferingStore
                output.append(stockItem.getAmount() + " ");
            } else {
                output.append("0 ");// no products available at currently selected store

            }
        } 
    } 
    output.append(" ;\n");
}

private java.util.Hashtable<org.cocome.tradingsystem.inventory.data.store.Store, java.lang.Integer> getStoreDistances(java.util.Collection<org.cocome.tradingsystem.inventory.data.store.Store> stores, org.cocome.tradingsystem.inventory.application.reporting.StoreTO callingStore) {
    java.util.Hashtable<org.cocome.tradingsystem.inventory.data.store.Store, java.lang.Integer> storeDistances = new java.util.Hashtable<org.cocome.tradingsystem.inventory.data.store.Store, java.lang.Integer>();
    java.util.Iterator<org.cocome.tradingsystem.inventory.data.store.Store> iterator = stores.iterator();
    while (iterator.hasNext()) {
        org.cocome.tradingsystem.inventory.data.store.Store currentStore = iterator.next();
        java.lang.String location = currentStore.getLocation();
        java.lang.String callingLocation = callingStore.getLocation();
        // currently simply abs(CompareTo):
        storeDistances.put(currentStore, java.lang.Math.abs(callingLocation.compareTo(location)));
    } 
    return storeDistances;
}

