private java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> removeUnavailableProducts(java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> requiredProductAmounts, java.util.Hashtable<org.cocome.tradingsystem.inventory.data.store.Store, java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem>> storeStockItems) {
    java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> foundProductAmounts = new java.util.ArrayList<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>();
    java.util.Iterator<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> requiredProductAmountsIterator = requiredProductAmounts.iterator();
    while (requiredProductAmountsIterator.hasNext()) {
        org.cocome.tradingsystem.inventory.application.store.ProductAmountTO currentProductAmountTO = requiredProductAmountsIterator.next();
        java.util.Iterator<java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem>> storeStockItemCollectionsIterator = storeStockItems.values().iterator();
        while (storeStockItemCollectionsIterator.hasNext()) {
            // iterate over stock of stores
            java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem> currentStockItemCollection = storeStockItemCollectionsIterator.next();
            org.cocome.tradingsystem.inventory.data.store.StockItem stockItem = org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.searchForProductOffered(currentStockItemCollection, currentProductAmountTO);
            if ((stockItem != null) && currentStockItemCollection.contains(stockItem)) {
                foundProductAmounts.add(currentProductAmountTO);
            } else {
                // TODO: remove debug:
                // System.out.println("KK: NOT found");
            }
            // no need to search for the same product at other stores: found --> available
            break;
        } 
    } 
    return foundProductAmounts;
}

