protected CoordinatorEventHandlerImpl(java.lang.String externalchannel) {
    super();
    try {
        this.topicName = externalchannel;
        this.jndiContext = new javax.naming.InitialContext();
        // get TopicConnectionFactory
        javax.jms.TopicConnectionFactory channelConnectionFactory = ((javax.jms.TopicConnectionFactory) (this.jndiContext.lookup(this.CHANNEL_CONNECTION_FACTORY)));
        // createTopicConnection
        javax.jms.TopicConnection topicConnection = channelConnectionFactory.createTopicConnection();
        // createTopicSession
        this.topicSession = topicConnection.createTopicSession(false, Session.AUTO_ACKNOWLEDGE);
        // getTopic
        javax.jms.Topic cashDeskTopic = ((javax.jms.Topic) (this.jndiContext.lookup(this.topicName)));
        javax.jms.TopicSubscriber topicSubscriber = this.topicSession.createSubscriber(cashDeskTopic);
        topicSubscriber.setMessageListener(this);
        this.coordinatorPublisher = this.topicSession.createPublisher(cashDeskTopic);
        topicConnection.start();
    } catch (javax.naming.NamingException e) {
        e.printStackTrace();
    } catch (javax.jms.JMSException e) {
        this.log.error(e);
        e.printStackTrace();
    }
}

