public void setValueAt(java.lang.Object value, int row, int col) {
    if (col == 10) {
        org.cocome.tradingsystem.inventory.application.store.StockItemTO sto = this.products.get(row).getStockItemTO();
        if ((sto != null) & (value instanceof java.lang.String)) {
            java.lang.String input = ((java.lang.String) (value));
            double price;
            try {
                price = java.lang.Double.parseDouble(input);
                double oldprice = sto.getSalesPrice();
                if (price != oldprice) {
                    sto.setSalesPrice(price);
                    try {
                        this.store.changePrice(sto);
                    } catch (java.rmi.RemoteException e) {
                        // TODO Auto-generated catch block
                        sto.setSalesPrice(oldprice);
                        e.printStackTrace();
                    }
                }
            } catch (java.lang.NumberFormatException e) {
                e.printStackTrace();
                // do nothing
            }
        }
    }
    this.fireTableCellUpdated(row, col);
}

