private void makeSale(org.cocome.tradingsystem.cashdeskline.datatypes.PaymentMode mode) throws javax.jms.JMSException {
    org.cocome.tradingsystem.inventory.application.store.SaleTO saleTO = new org.cocome.tradingsystem.inventory.application.store.SaleTO();
    saleTO.setProductTOs(this.products);
    // The old synchronous call
    /* inventory.bookSale(saleTO); */
    this.appPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.SaleSuccessEvent()));
    // goes to store
    this.externalPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.AccountSaleEvent(saleTO)));
    // goes to coordinator
    this.externalPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.SaleRegisteredEvent(this.topicName, saleTO.getProductTOs().size(), mode)));
}

public static org.cocome.tradingsystem.inventory.application.store.StockItemTO fillStockItemTO(org.cocome.tradingsystem.inventory.data.store.StockItem stockitem) {
