    result.setId(stockitem.getId());
    result.setAmount(stockitem.getAmount());
    result.setMinStock(stockitem.getMinStock());
    result.setMaxStock(stockitem.getMaxStock());
    result.setSalesPrice(stockitem.getSalesPrice());
    return result;
}

public static org.cocome.tradingsystem.inventory.application.store.ProductWithSupplierAndStockItemTO fillProductWithSupplierAndStockItemTO(org.cocome.tradingsystem.inventory.data.store.StoreQueryIf storequery, long storeid, org.cocome.tradingsystem.inventory.data.enterprise.Product product, org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx) {
    org.cocome.tradingsystem.inventory.application.store.ProductWithSupplierAndStockItemTO result = new org.cocome.tradingsystem.inventory.application.store.ProductWithSupplierAndStockItemTO();
    result.setSupplierTO(org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillSupplierTO(product.getSupplier()));
    result.setId(product.getId());
    result.setName(product.getName());
    result.setBarcode(product.getBarcode());
    result.setPurchasePrice(product.getPurchasePrice());
    org.cocome.tradingsystem.inventory.data.store.StockItem stockitem = storequery.queryStockItem(storeid, product.getBarcode(), pctx);
    if (stockitem != null) {
        result.setStockItemTO(org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillStockItemTO(stockitem));
    }
    return result;
}

