public org.cocome.tradingsystem.inventory.application.store.StoreWithEnterpriseTO getStore() {
    org.cocome.tradingsystem.inventory.application.store.StoreWithEnterpriseTO result = null;
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        result = org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillStoreWithEnterpriseTO(this.storequery.queryStoreById(this.storeid, pctx));
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
    return result;
}

