public void onMessage(javax.jms.Message message) {
    if (message instanceof javax.jms.ObjectMessage) {
        javax.jms.ObjectMessage objMessage = ((javax.jms.ObjectMessage) (message));
        try {
            java.io.Serializable eventObject = objMessage.getObject();
            // A RunningTotalChangedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.RunningTotalChangedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.RunningTotalChangedEvent runningTotalChangedEvent = ((org.cocome.tradingsystem.cashdeskline.events.RunningTotalChangedEvent) (eventObject));
                this.onEvent(runningTotalChangedEvent);
            }
            // A CashAmountEnteredEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.CashAmountEnteredEvent) {
                org.cocome.tradingsystem.cashdeskline.events.CashAmountEnteredEvent cashAmountEnteredEvent = ((org.cocome.tradingsystem.cashdeskline.events.CashAmountEnteredEvent) (eventObject));
                this.onEvent(cashAmountEnteredEvent);
            }
            // A ChangeAmountCalculatedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ChangeAmountCalculatedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ChangeAmountCalculatedEvent changeAmountCalculatedEvent = ((org.cocome.tradingsystem.cashdeskline.events.ChangeAmountCalculatedEvent) (eventObject));
                this.onEvent(changeAmountCalculatedEvent);
            }
            // A ExpressModeDisabledEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent expressModeDisabledEvent = ((org.cocome.tradingsystem.cashdeskline.events.ExpressModeDisabledEvent) (eventObject));
                this.onEvent(expressModeDisabledEvent);
            }
            // A ExpressModeEnabledEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent expressModeEnabledEvent = ((org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent) (eventObject));
                this.onEvent(expressModeEnabledEvent);
            }
            // A InvalidCreditCardEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.InvalidCreditCardEvent) {
                org.cocome.tradingsystem.cashdeskline.events.InvalidCreditCardEvent invalidCreditCardEvent = ((org.cocome.tradingsystem.cashdeskline.events.InvalidCreditCardEvent) (eventObject));
                this.onEvent(invalidCreditCardEvent);
            }
            // A CreditCardScanFailedEvent has been received
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.CreditCardScanFailedEvent) {
                org.cocome.tradingsystem.cashdeskline.events.CreditCardScanFailedEvent creditCardScanFailedEvent = ((org.cocome.tradingsystem.cashdeskline.events.CreditCardScanFailedEvent) (eventObject));
                this.onEvent(creditCardScanFailedEvent);
            }
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.ProductBarcodeNotValidEvent) {
                org.cocome.tradingsystem.cashdeskline.events.ProductBarcodeNotValidEvent productBarcodeNotValidEvent = ((org.cocome.tradingsystem.cashdeskline.events.ProductBarcodeNotValidEvent) (eventObject));
                this.onEvent(productBarcodeNotValidEvent);
            }
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.SaleSuccessEvent) {
                org.cocome.tradingsystem.cashdeskline.events.SaleSuccessEvent saleSuccessEvent = ((org.cocome.tradingsystem.cashdeskline.events.SaleSuccessEvent) (eventObject));
                this.onEvent(saleSuccessEvent);
            }
            if (eventObject instanceof org.cocome.tradingsystem.cashdeskline.events.SaleStartedEvent) {
