public void bookSale(org.cocome.tradingsystem.inventory.application.store.SaleTO saleTO) {
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        for (org.cocome.tradingsystem.inventory.application.store.ProductWithStockItemTO pwsto : saleTO.getProductTOs()) {
            org.cocome.tradingsystem.inventory.data.store.StockItem si = this.storequery.queryStockItemById(pwsto.getStockItemTO().getId(), pctx);
            // TODO: THIS CLASS IS USED IN 2 DIFFERENT WAYS!!!
            si.setAmount(si.getAmount() - 1);
        }
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
    // permanent check; required for UC 8
    // (alternative design decision: check initiated by timer event)
    this.checkForLowRunningGoods();
}

