                org.cocome.tradingsystem.inventory.application.reporting.StoreTO store = new org.cocome.tradingsystem.inventory.application.reporting.StoreTO();
                store.setId(storeId);
                org.cocome.tradingsystem.inventory.application.reporting.ReportTO report;
