public org.cocome.tradingsystem.inventory.application.reporting.ReportTO getMeanTimeToDeliveryReport(org.cocome.tradingsystem.inventory.application.reporting.EnterpriseTO enterpriseTO) {
    org.cocome.tradingsystem.inventory.application.reporting.ReportTO result = new org.cocome.tradingsystem.inventory.application.reporting.ReportTO();
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    java.lang.StringBuilder reportText = new java.lang.StringBuilder("");
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        reportText.append("<html><body>");
        org.cocome.tradingsystem.inventory.data.enterprise.TradingEnterprise enterprise = this.enterprisequery.queryEnterpriseById(enterpriseTO.getId(), pctx);
        reportText.append("<table><tr>" + ((("<th>Supplier ID</th>" + "<th>Supplier Name</th>") + "<th>Mean Time To Delivery</th>") + "</tr>"));
        for (org.cocome.tradingsystem.inventory.data.enterprise.ProductSupplier supplier : enterprise.getSuppliers()) {
            long mtdelivery = this.enterprisequery.getMeanTimeToDelivery(supplier, enterprise, pctx);
            if (mtdelivery == 0) {
                continue;
            }
            reportText.append(((((((((("<tr>" + "<td>") + supplier.getId()) + "</td>") + "<td>") + supplier.getName()) + "</td>") + "<td>") + mtdelivery) + "</td>") + "</tr>");
        }
        reportText.append("</table>");
        reportText.append("</body></html>");
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
    result.setReportText(reportText.toString());
    return result;
}

public void onEvent(org.cocome.tradingsystem.cashdeskline.events.PINEnteredEvent pinEnteredEvent) {
    this.log.info("Application: PINEnteredEvent received");
    if (this.currState.equals(org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.CREDIT_CARD_SCANNED)) {
        try {
            org.cocome.tradingsystem.external.Bank bank = ((org.cocome.tradingsystem.external.Bank) (this.connect(this.bankname)));
            this.transactionid = bank.validateCard(this.cardInformation, pinEnteredEvent.getPIN());
            if (this.transactionid == null) {
                this.appPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.InvalidCreditCardEvent()));
                this.topicSession.commit();
                return;
            }
            org.cocome.tradingsystem.external.Debit info = bank.debitCard(this.transactionid);
            if (info.equals(org.cocome.tradingsystem.external.Debit.OK)) {
                // make the sale
                this.makeSale(org.cocome.tradingsystem.cashdeskline.datatypes.PaymentMode.CREDITCARD);
                this.topicSession.commit();
                this.reset();
                this.currState = org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.INITIALIZED;
            }
            if (info.equals(org.cocome.tradingsystem.external.Debit.TRANSACTION_ID_NOT_VALID)) {
                // we have to rescan the card
                this.log.info("Transaction id not valid");
                this.appPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.InvalidCreditCardEvent()));
                this.topicSession.commit();
                this.currState = org.cocome.tradingsystem.cashdeskline.cashdesk.application.impl.CashDeskStates.PAYING_BY_CREDITCARD;
            }
            if (info.equals(org.cocome.tradingsystem.external.Debit.NOT_ENOUGH_MONEY)) {
                // Other failures
                // TODO: this has to be refined
                this.log.info("Not enough money on the account");
                this.appPublisher.publish(this.topicSession.createObjectMessage(new org.cocome.tradingsystem.cashdeskline.events.InvalidCreditCardEvent()));
                this.topicSession.commit();
            }
        } catch (java.rmi.RemoteException e) {
            e.printStackTrace();
            try {
                this.topicSession.rollback();
            } catch (javax.jms.JMSException e1) {
                e1.printStackTrace();
            }
        } catch (javax.jms.JMSException e) {
            e.printStackTrace();
            try {
                this.topicSession.rollback();
            } catch (javax.jms.JMSException e1) {
                e1.printStackTrace();
            }
        }
    }
    try {
        this.topicSession.commit();
    } catch (javax.jms.JMSException e) {
        e.printStackTrace();
    }
}

private java.rmi.Remote connect(java.lang.String name) throws java.rmi.RemoteException {
    if (java.lang.System.getSecurityManager() == null) {
        java.lang.System.setSecurityManager(new java.rmi.RMISecurityManager());
    }
    try {
        java.rmi.registry.Registry r = java.rmi.registry.LocateRegistry.getRegistry(this.registrybaseurl, this.registryport);
        return r.lookup(name);
    } catch (java.rmi.NotBoundException e) {
        e.printStackTrace();
        throw new java.rmi.RemoteException("NotBoundException", e);
    }
}

