public java.util.Hashtable<org.cocome.tradingsystem.inventory.application.reporting.StoreTO, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>> solveOptimization(java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> requiredProductAmounts, java.util.Hashtable<org.cocome.tradingsystem.inventory.data.store.Store, java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem>> storeStockItems, java.util.Hashtable<org.cocome.tradingsystem.inventory.data.store.Store, java.lang.Integer> storeDistances) {
    java.util.Hashtable<org.cocome.tradingsystem.inventory.application.reporting.StoreTO, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>> returnTable = new java.util.Hashtable<org.cocome.tradingsystem.inventory.application.reporting.StoreTO, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>>();
    java.lang.StringBuffer output = new java.lang.StringBuffer();
    org.netlib.ampl.Ampl ampl = null;
    // grant pre-conditions of the solver:
    requiredProductAmounts = this.removeUnavailableProducts(requiredProductAmounts, storeStockItems);
    // pre-condition: > 0 product remain required after removeUnavailableProducts()
    if (requiredProductAmounts.size() > 0) {
        // else empty hashtable is returned
        try {
            // create the data input file
            org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.createTmpFile(org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.amplDir + "cocome.dat", org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.createDataString(requiredProductAmounts, storeStockItems, storeDistances));
            // set up commands for ampl:
            java.lang.String amplCommands = ((((((("option solver " + ("cplex.exe;\n" + "model ")) + org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.amplDir) + "cocome.mod;\n") + "data ") + org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.amplDir) + "cocome.dat;\n") + "solve;\n") + "display shipping_amount;\n";
            // execute the command line solver: AMPL / CPLEX
            ampl = new org.netlib.ampl.Ampl(org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.amplCmd);
            ampl.send(amplCommands);
            output.append(ampl.rcv());
        } catch (java.lang.Exception e) {
            java.lang.System.err.println((e + " starting ") + org.cocome.tradingsystem.inventory.application.productdispatcher.impl.AmplStarter.amplCmd);
            e.printStackTrace();
        }
        java.lang.System.out.println(output);
        returnTable = this.parseOutput(output.toString());
    }
    return returnTable;
}

