        public void actionPerformed(java.awt.event.ActionEvent e) {
            if (e.getSource() == b) {
                b.actionPerformed(e);
            }
        }
    });
    b.setSize(50, 100);
    this.add(b, java.awt.BorderLayout.PAGE_START);
    // Register elements to Refresh Button
    b.addElem(ptm);
    b.addElem(psm);
    b.addElem(pssm);
    b.addElem(psom);
    b.addElem(storedescr);
    // Add the tabbed pane to this panel.
    this.add(tabbedPane);
}

