public void onEvent(org.cocome.tradingsystem.cashdeskline.events.ExpressModeEnabledEvent expressModeEnabledEvent) {
    this.log.info("Application: ExpressModeEnabledEvent received");
    if ((!this.expressModeEnabled) && expressModeEnabledEvent.getCashdesk().equals(this.topicName)) {
        try {
            this.appPublisher.publish(this.topicSession.createObjectMessage(expressModeEnabledEvent));
            this.topicSession.commit();
            this.expressModeEnabled = true;
        } catch (javax.jms.JMSException e) {
            e.printStackTrace();
            try {
                this.topicSession.rollback();
            } catch (javax.jms.JMSException e1) {
                e1.printStackTrace();
            }
        }
    }
}

