public org.cocome.tradingsystem.inventory.data.store.StockItem queryStockItem(long storeId, long productbarcode, org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx) {
    javax.persistence.EntityManager em = ((org.cocome.tradingsystem.inventory.data.persistence.impl.PersistenceContextImpl) (pctx)).getEntityManager();
    org.cocome.tradingsystem.inventory.data.store.StockItem result = null;
    java.util.Collection<org.cocome.tradingsystem.inventory.data.enterprise.Product> prodref = em.createQuery("select product from Product as product where product.barcode = ?1").setParameter(1, productbarcode).getResultList();
    if (prodref.size() == 0) {
        return null;
    }
    org.cocome.tradingsystem.inventory.data.store.Store store = em.getReference(org.cocome.tradingsystem.inventory.data.store.Store.class, storeId);
    java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem> results = em.createQuery("select stockitem from StockItem as stockitem where stockitem.store = ?1 and stockitem.product = ?2").setParameter(1, store).setParameter(2, prodref.iterator().next()).getResultList();
    // TODO: print Error if result.size() > 1
    if (results.size() > 0) {
        result = results.iterator().next();
    }
    return result;
}

public static void main(java.lang.String[] args) throws java.rmi.RemoteException {
    int port;
    if (args.length == 0) {
        throw new java.lang.IllegalArgumentException();
    }
    if (args.length < 1) {
        port = 1099;
    } else {
        port = java.lang.Integer.valueOf(args[0]).intValue();
    }
    try {
        if (java.lang.System.getSecurityManager() == null) {
            java.lang.System.setSecurityManager(new java.rmi.RMISecurityManager());
        }
        new sun.rmi.registry.RegistryImpl(port);
        // LocateRegistry.createRegistry(port);
        java.io.DataInput in = new java.io.DataInputStream(java.lang.System.in);
        // Serve clients
        while (true) {
            java.lang.System.out.println("Type EXIT to shutdown the registry.");
            if ("EXIT".equalsIgnoreCase(in.readLine())) {
                break;
            }
        } 
        java.lang.System.out.println("BYE");
    } catch (java.lang.Exception e) {
        java.lang.System.err.println("Server exception: " + e.toString());
        e.printStackTrace();
        java.lang.System.exit(2);
    }
}

