public java.util.List<org.cocome.tradingsystem.inventory.application.store.ProductWithSupplierAndStockItemTO> getAllProductsWithOptionalStockItem() {
    java.util.List<org.cocome.tradingsystem.inventory.application.store.ProductWithSupplierAndStockItemTO> result = new java.util.ArrayList<org.cocome.tradingsystem.inventory.application.store.ProductWithSupplierAndStockItemTO>();
    org.cocome.tradingsystem.inventory.data.persistence.PersistenceContext pctx = this.persistmanager.getPersistenceContext();
    org.cocome.tradingsystem.inventory.data.persistence.TransactionContext tx = null;
    try {
        tx = pctx.getTransactionContext();
        tx.beginTransaction();
        java.util.Collection<org.cocome.tradingsystem.inventory.data.enterprise.Product> products = this.storequery.queryProducts(this.storeid, pctx);
        for (org.cocome.tradingsystem.inventory.data.enterprise.Product p : products) {
            result.add(org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillProductWithSupplierAndStockItemTO(this.storequery, this.storeid, p, pctx));
        }
        tx.commit();
    } catch (java.lang.RuntimeException e) {
        if ((tx != null) && tx.isActive()) {
            tx.rollback();
        }
        e.printStackTrace();
        throw e;// or display error message

    } finally {
        pctx.close();
    }
    return result;
}

