private static org.cocome.tradingsystem.inventory.data.store.StockItem searchForProductOffered(java.util.Collection<org.cocome.tradingsystem.inventory.data.store.StockItem> offeredStockItems, org.cocome.tradingsystem.inventory.application.store.ProductAmountTO currentRequiredProduct) {
    java.util.Iterator<org.cocome.tradingsystem.inventory.data.store.StockItem> stockItemIterator = offeredStockItems.iterator();
    org.cocome.tradingsystem.inventory.data.store.StockItem currentStockItem;
    while (stockItemIterator.hasNext()) {
        currentStockItem = stockItemIterator.next();
        org.cocome.tradingsystem.inventory.application.store.ProductTO productTO = org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillProductTO(currentStockItem.getProduct());
        if (productTO.equals(currentRequiredProduct.getProduct())) {
            return currentStockItem;
        }
    } 
    return null;
}

