private java.util.Hashtable<org.cocome.tradingsystem.inventory.application.reporting.StoreTO, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>> parseOutput(java.lang.String output) {
    java.util.Hashtable<org.cocome.tradingsystem.inventory.application.reporting.StoreTO, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>> resultList = new java.util.Hashtable<org.cocome.tradingsystem.inventory.application.reporting.StoreTO, java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>>();
    de.uka.ipd.sdq.cplexparser.ICplexParser parser = new de.uka.ipd.sdq.cplexparser.impl.CplexParser();
    try {
        java.util.List<de.uka.ipd.sdq.cplexparser.impl.Store> stores = parser.parseString(output);
        if (stores == null) {
            // no or not enough products offered
            return resultList;// return empty list

        }
        org.cocome.tradingsystem.inventory.data.store.Store currentStore;
        org.cocome.tradingsystem.inventory.application.reporting.StoreTO currentStoreTO;
        org.cocome.tradingsystem.inventory.data.enterprise.Product currentProduct;
        org.cocome.tradingsystem.inventory.application.store.ProductTO currentProductTO;
        org.cocome.tradingsystem.inventory.application.store.ProductAmountTO currentProductAmountTO;
        for (de.uka.ipd.sdq.cplexparser.impl.Store s : stores) {
            // (SDQ)Store --> Store --> StoreID
            currentStore = this.storeQuery.queryStoreById(s.getAttributeId(), this.pctx);
            currentStoreTO = org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillStoreTO(currentStore);
            // System.out.println(" Store "+s.getName());
            java.util.List<de.uka.ipd.sdq.cplexparser.impl.Product> products = s.getProductList();
            java.util.Collection<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO> productsTOs = new java.util.ArrayList<org.cocome.tradingsystem.inventory.application.store.ProductAmountTO>();
            for (de.uka.ipd.sdq.cplexparser.impl.Product p : products) {
                // (SDQ)Product --> Product --> ProductTO
                currentProduct = this.storeQuery.queryProductById(p.getAttributeId(), this.pctx);
                currentProductTO = org.cocome.tradingsystem.inventory.application.store.impl.FillTransferObjects.fillProductTO(currentProduct);
                currentProductAmountTO = new org.cocome.tradingsystem.inventory.application.store.ProductAmountTO();
                currentProductAmountTO.setProduct(currentProductTO);
                currentProductAmountTO.setAmount(p.getAmount());
                // System.out.println("  Product "+ p.getName()+ " "+p.getAmount());
                productsTOs.add(currentProductAmountTO);
            }
            resultList.put(currentStoreTO, productsTOs);
        }
    } catch (de.uka.ipd.sdq.cplexparser.exception.CplexParserException e) {
        e.printStackTrace();
        java.lang.System.err.println("AMPL/CPLEX Parse Error for UC 8 Optimization");
        // throw new RuntimeException("AMPL/CPLEX Parse Error for UC 8 Optimization", e);
    }
    return resultList;
}
